def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find connected non-background, non-wall components.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] in (0, 5) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            g[ny][nx] not in (0, 5) and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    # Find maximal straight runs of 5s.
    runs = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and g[r][c] == 5:
                c += 1
            if c - start >= 2:
                runs.append(("H", r, start, c - 1))
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and g[r][c] == 5:
                r += 1
            if r - start >= 2:
                runs.append(("V", c, start, r - 1))

    for orient, fixed, lo, hi in runs:
        for comp in components:
            rmin = min(r for r, c in comp)
            rmax = max(r for r, c in comp)
            cmin = min(c for r, c in comp)
            cmax = max(c for r, c in comp)
            cells = set(comp)

            if orient == "H":
                # A colored component on either side of a horizontal run.
                side = (rmax < fixed or rmin > fixed)
                overlap = cmin <= hi and cmax >= lo
                adjacent = any(
                    (fixed - 1, c) in cells or (fixed + 1, c) in cells
                    for c in range(lo, hi + 1)
                )
                if not (side and overlap and adjacent):
                    continue
                for r in range(rmin, rmax + 1):
                    for c in range(lo, hi + 1):
                        g[r][c] = grid[rmin + (r - rmin) % (rmax - rmin + 1)][
                            cmin + (c - cmin) % (cmax - cmin + 1)
                        ]
            else:
                # A colored component on either side of a vertical run.
                side = (cmax < fixed or cmin > fixed)
                overlap = rmin <= hi and rmax >= lo
                adjacent = any(
                    (r, fixed - 1) in cells or (r, fixed + 1) in cells
                    for r in range(lo, hi + 1)
                )
                if not (side and overlap and adjacent):
                    continue
                for r in range(lo, hi + 1):
                    for c in range(cmin, cmax + 1):
                        g[r][c] = grid[rmin + (r - rmin) % (rmax - rmin + 1)][
                            cmin + (c - cmin) % (cmax - cmin + 1)
                        ]

    return g
